def slide(label,title,subtitle,body='',dark=False,number=0,photo=None):
    return f'''<section class="slide {'dark' if dark else ''}"><div class="topline"><span>✚ MEDIPICK</span><span>{html.escape(label)}</span></div><div class="inner"><div class="kicker">{html.escape(label)}</div><h1>{title}</h1><p class="subtitle">{subtitle}</p>{body}</div><div class="bottomline"><span>CONFIDENTIAL · DISCUSSION DRAFT · 2026.10.29</span><span>{number:02d} / 14</span></div>{f'<img class="corner-photo" src="{PHOTOS}{photo}" alt="AI-generated illustrative medical photo">' if photo else ''}</section>'''
def cards(items):return '<div class="cards">'+''.join(f'<article><h3>{a}</h3><p>{b}</p></article>' for a,b in items)+'</div>'
def bullets(items):return '<ul class="bullets">'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def cols(l,r):return '<div class="two"><div>'+l+'</div><div>'+r+'</div></div>'
def pill(text):return '<span class="tag">'+text+'</span>'
def bars(title,items):return '<div class="bars"><h3>'+title+'</h3>'+''.join(f'<div class="bar-row"><span>{n}</span><div class="track"><div style="width:{v}%"></div></div><b>{label}</b></div>' for n,v,label in items)+'</div>'
def steps(items):return '<div class="steps">'+''.join(f'<article><b>{i+1:02d}</b><h3>{n}</h3><p>{x}</p></article>' for i,(n,x) in enumerate(items))+'</div>'
def metrics(items):return '<div class="metrics">'+''.join(f'<article><strong>{n}</strong><b>{t}</b><small>{x}</small></article>' for n,t,x in items)+'</div>'
def footer_sources():return '<div class="sources"><b>Reference sources / 출처</b><p>① <a href="https://www.nhic.kr/announce/wbhaec11404m01.do">NHIS annual healthcare institutions; 2026 Q2 (2026-06-30)</a> ② <a href="https://datareportal.com/reports/digital-2026-south-korea">DataReportal Digital 2026 South Korea (Oct 2025 basis)</a> ③ <a href="https://www.law.go.kr/LSW/lsLinkCommonInfo.do?chrClsCd=010202&lsJoLnkSeq=1031169873">Medical Service Act §56, Oct 2026</a> ④ <a href="https://developers.google.com/maps/documentation/places/web-service/policies">Google Maps Platform policy</a> ⑤ <a href="https://developers.google.com/blogger/docs/3.0/reference/blogs/getByUrl">Blogger API</a> ⑥ <a href="https://developers.google.com/search/docs/fundamentals/creating-helpful-content">Google Search helpful content / YMYL</a>. Numbers: public institutional reference, not MEDIPICK current performance. Financials: illustrative management scenarios only.</p></div>'
